func TestEnumActorKind(t *testing.T) {
	t.Run("NewFromString_user", func(t *testing.T) {
		t.Parallel()
		val, err := NewActorKindFromString("user")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ActorKind("user"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_service", func(t *testing.T) {
		t.Parallel()
		val, err := NewActorKindFromString("service")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ActorKind("service"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_system", func(t *testing.T) {
		t.Parallel()
		val, err := NewActorKindFromString("system")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ActorKind("system"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewActorKindFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewActorKindFromString("user")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

func TestEnumChecksumAlgorithm(t *testing.T) {
	t.Run("NewFromString_sha256", func(t *testing.T) {
		t.Parallel()
		val, err := NewChecksumAlgorithmFromString("sha256")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ChecksumAlgorithm("sha256"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_crc64nvme", func(t *testing.T) {
		t.Parallel()
		val, err := NewChecksumAlgorithmFromString("crc64nvme")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ChecksumAlgorithm("crc64nvme"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_crc32c", func(t *testing.T) {
		t.Parallel()
		val, err := NewChecksumAlgorithmFromString("crc32c")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ChecksumAlgorithm("crc32c"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewChecksumAlgorithmFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewChecksumAlgorithmFromString("sha256")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

